#!/usr/bin/env bun

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  tags: string[];
  status: Status;
  createdAt: string;
  due?: string;
  completedAt?: string;
}

interface Database {
  nextId: number;
  tasks: Task[];
}

const output = (value: unknown): void => console.log(JSON.stringify(value));
const fail = (message: string): never => {
  console.error(message);
  process.exit(1);
};

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
}

function today(): string {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60_000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function databasePath(): string {
  return process.env.TASKBOARD_FILE || `${process.cwd()}/.taskboard.json`;
}

function validateDatabase(value: unknown): Database {
  if (!value || typeof value !== "object") throw new Error("database must be an object");
  const db = value as Partial<Database>;
  if (!Number.isSafeInteger(db.nextId) || (db.nextId ?? 0) < 1 || !Array.isArray(db.tasks)) {
    throw new Error("database has invalid schema");
  }
  const ids = new Set<number>();
  for (const task of db.tasks) {
    if (!task || typeof task !== "object" || !Number.isSafeInteger(task.id) || task.id < 1 ||
        typeof task.title !== "string" || !Array.isArray(task.tags) ||
        (task.status !== "open" && task.status !== "done") || typeof task.createdAt !== "string" ||
        (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) ||
        (task.completedAt !== undefined && typeof task.completedAt !== "string") || ids.has(task.id)) {
      throw new Error("database has invalid task data");
    }
    ids.add(task.id);
  }
  if (db.tasks.some((task) => task.id >= (db.nextId as number))) throw new Error("database has invalid nextId");
  return db as Database;
}

async function load(): Promise<Database> {
  const path = databasePath();
  const file = Bun.file(path);
  if (!(await file.exists())) return { nextId: 1, tasks: [] };
  let parsed: unknown;
  try {
    parsed = JSON.parse(await file.text());
  } catch {
    throw new Error("database contains invalid JSON");
  }
  return validateDatabase(parsed);
}

async function save(db: Database): Promise<void> {
  const path = databasePath();
  const temp = `${path}.tmp-${process.pid}-${crypto.randomUUID()}`;
  try {
    await Bun.write(temp, `${JSON.stringify(db, null, 2)}\n`);
    await Bun.write(path, Bun.file(temp));
    // Bun.write does not expose rename; use Bun's shell only after the temp file exists.
    await Bun.$`mv -f ${temp} ${path}`.quiet();
  } catch (error) {
    try { await Bun.$`rm -f ${temp}`.quiet(); } catch { /* best effort */ }
    throw error;
  }
}

function parseFlags(args: string[], allowed: readonly string[]): Map<string, string> {
  const flags = new Map<string, string>();
  for (let i = 0; i < args.length; i += 2) {
    const flag = args[i];
    const value = args[i + 1];
    if (!flag?.startsWith("--") || !allowed.includes(flag) || value === undefined || flags.has(flag)) {
      throw new Error(`invalid flag: ${flag ?? ""}`);
    }
    flags.set(flag, value);
  }
  return flags;
}

function normalizeTags(input: string): string[] {
  return [...new Set(input.split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
}

function taskId(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value)) throw new Error("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id) || id < 1) throw new Error("ID must be a positive integer");
  return id;
}

async function main(): Promise<void> {
  const [command, ...args] = process.argv.slice(2);
  if (!command) throw new Error("missing command");
  const db = await load();

  if (command === "add") {
    const flags = parseFlags(args, ["--title", "--tags", "--due"]);
    const title = flags.get("--title")?.trim();
    if (!title) throw new Error("--title is required and cannot be empty");
    const due = flags.get("--due");
    if (due !== undefined && !isDate(due)) throw new Error("--due must be a valid YYYY-MM-DD date");
    const task: Task = { id: db.nextId++, title, tags: normalizeTags(flags.get("--tags") ?? ""), status: "open", createdAt: new Date().toISOString() };
    if (due !== undefined) task.due = due;
    db.tasks.push(task);
    await save(db);
    output(task);
    return;
  }

  if (command === "list") {
    const flags = parseFlags(args, ["--status", "--tag", "--overdue"]);
    const status = flags.get("--status");
    const tag = flags.get("--tag")?.trim().toLowerCase();
    const overdue = flags.get("--overdue");
    if (status !== undefined && status !== "open" && status !== "done") throw new Error("--status must be open or done");
    if (overdue !== undefined && !isDate(overdue)) throw new Error("--overdue must be a valid YYYY-MM-DD date");
    output(db.tasks.filter((task) =>
      (status === undefined || task.status === status) &&
      (!tag || task.tags.includes(tag)) &&
      (overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
    ).sort((a, b) => a.id - b.id));
    return;
  }

  if (command === "done" || command === "delete") {
    if (args.length !== 1) throw new Error(`${command} requires exactly one ID`);
    const id = taskId(args[0]);
    const index = db.tasks.findIndex((task) => task.id === id);
    if (index === -1) throw new Error(`task ${id} not found`);
    if (command === "done") {
      const task = db.tasks[index];
      if (task.status === "open") { task.status = "done"; task.completedAt = new Date().toISOString(); await save(db); }
      output(task);
    } else {
      const [task] = db.tasks.splice(index, 1);
      await save(db);
      output(task);
    }
    return;
  }

  if (command === "stats") {
    if (args.length !== 0) throw new Error("stats accepts no arguments");
    const open = db.tasks.filter((task) => task.status === "open");
    output({ total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter((task) => task.due && task.due < today()).length });
    return;
  }
  throw new Error(`unknown command: ${command}`);
}

