  if (!command) throw new Error("missing command");
  const db = await load();

  if (command === "add") {
    const flags = parseFlags(args, ["--title", "--tags", "--due"]);
    const title = flags.get("--title")?.trim();
    if (!title) throw new Error("--title is required and cannot be empty");
    const due = flags.get("--due");
    if (due !== undefined && !isDate(due)) throw new Error("--due must be a valid YYYY-MM-DD date");
    const task: Task = { id: db.nextId++, title, tags: normalizeTags(flags.get("--tags") ?? ""), status: "open", createdAt: new Date().toISOString() };
    if (due !== undefined) task.due = due;
    db.tasks.push(task);
    await save(db);
    output(task);
    return;
  }

  if (command === "list") {
    const flags = parseFlags(args, ["--status", "--tag", "--overdue"]);
    const status = flags.get("--status");
    const tag = flags.get("--tag")?.trim().toLowerCase();
    const overdue = flags.get("--overdue");
    if (status !== undefined && status !== "open" && status !== "done") throw new Error("--status must be open or done");
    if (overdue !== undefined && !isDate(overdue)) throw new Error("--overdue must be a valid YYYY-MM-DD date");
    output(db.tasks.filter((task) =>
      (status === undefined || task.status === status) &&
      (!tag || task.tags.includes(tag)) &&
      (overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
    ).sort((a, b) => a.id - b.id));
    return;
  }

  if (command === "done" || command === "delete") {
    if (args.length !== 1) throw new Error(`${command} requires exactly one ID`);
    const id = taskId(args[0]);
    const index = db.tasks.findIndex((task) => task.id === id);
    if (index === -1) throw new Error(`task ${id} not found`);
    if (command === "done") {
      const task = db.tasks[index];
      if (task.status === "open") { task.status = "done"; task.completedAt = new Date().toISOString(); await save(db); }
      output(task);
    } else {
      const [task] = db.tasks.splice(index, 1);
      await save(db);
      output(task);
    }
    return;
  }

  if (command === "stats") {
    if (args.length !== 0) throw new Error("stats accepts no arguments");
    const open = db.tasks.filter((task) => task.status === "open");
    output({ total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter((task) => task.due && task.due < today()).length });
    return;
  }
  throw new Error(`unknown command: ${command}`);
}

main().catch((error: unknown) => fail(error instanceof Error ? error.message : String(error)));

--- README ---
# Taskboard CLI

A dependency-free task manager for Bun. Data is stored in `.taskboard.json` in the current directory, or at the path specified by `TASKBOARD_FILE`.

```sh
bun run src/cli.ts add --title "Ship release" --tags work,urgent --due 2026-09-10
bun run src/cli.ts list --status open --tag work
bun run src/cli.ts done 1
bun run src/cli.ts stats
bun run src/cli.ts delete 1
```

Every command writes exactly one JSON value to standard output. Errors are written to standard error and exit non-zero. Tags are trimmed, lowercased, and deduplicated. `list --overdue YYYY-MM-DD` includes only open tasks due before that date.

## Self-test

```sh
bun test
```

--- TEST ---
import { afterEach, describe, expect, test } from "bun:test";

const root = new URL("..", import.meta.url).pathname;
const db = `/tmp/taskboard-cli-test-${process.pid}-${crypto.randomUUID()}.json`;
const run = (...args: string[]) => Bun.$`TASKBOARD_FILE=${db} bun run src/cli.ts ${args}`.cwd(root).quiet();

afterEach(async () => { await Bun.$`rm -f ${db}`.quiet(); });

describe("taskboard", () => {
  test("persists, filters, completes and reports stats", async () => {
    const added = await run("add", "--title", " First ", "--tags", "Work, work, urgent", "--due", "2020-02-29");
    expect(JSON.parse(added.text())).toMatchObject({ id: 1, title: "First", tags: ["work", "urgent"], status: "open", due: "2020-02-29" });
    await run("add", "--title", "Second");
    expect(JSON.parse((await run("list", "--tag", "WORK", "--overdue", "2021-01-01")).text())).toHaveLength(1);
    const done = JSON.parse((await run("done", "1")).text());
    expect(done.status).toBe("done");
    expect(JSON.parse((await run("stats")).text())).toMatchObject({ total: 2, open: 1, done: 1, overdue: 0 });
    expect((await run("done", "1")).exitCode).toBe(0);
  });

  test("rejects invalid input without overwriting database", async () => {
    await run("add", "--title", "Safe");
    const result = await run("add", "--title", "", "--due", "2026-02-30").nothrow();
    expect(result.exitCode).not.toBe(0);
    expect(JSON.parse((await run("list")).text())).toHaveLength(1);
  });
});

